# A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet ({"to": <person id>}). Responds with the sheet's claims.
validate:
  class: net.officefloor.hq.app.claim.ValidateReassign
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: reassign
reassign:
  class: net.officefloor.hq.app.claim.ReassignClaim
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaims
  govern: [ transaction ]
# Validate before load so a bad date is a 400, not masked by a 404. Responds with the sheet's people.
validate:
  class: net.officefloor.hq.app.person.ValidateRetire
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: retire
retire:
  class: net.officefloor.hq.app.person.RetirePerson
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPeople
  govern: [ transaction ]
# Adds an alias to the person: refused (400, nothing written) when blank or equal, ignoring case, to any name or
# alias on the sheet. Responds with the sheet's aliases.
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: add
add:
  class: net.officefloor.hq.app.alias.AddAlias
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.alias.RespondWithAliases
  govern: [ transaction ]
handle:
  class: net.officefloor.hq.app.person.HandleInvalidPerson
package net.officefloor.hq.app.person;

