package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Moves the claim to another person on the sheet by the rules of {@link ClaimReassigner}. */
public class ReassignClaim {
    public void reassign(@PathVariable("sheet") String sheet, @RequestParam("user") String user,
            @Val ReassignRequest body, @Val Claim claim, ClaimReassigner reassigner)
            throws InvalidClaimStatusChangeException {
        reassigner.reassign(sheet, user, claim, body.to(), false);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the reassign body once, refusing one that names no person. */
public class ValidateReassign {
    public void validate(@RequestBody ReassignRequest request, Out<ReassignRequest> body)
            throws InvalidClaimStatusChangeException {
        if (request == null || request.to() == null) {
            throw new InvalidClaimStatusChangeException("A reassign names the person the claim moves to");
        }
        body.set(request);
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Late;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Dated;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: each person's claimed, due-total and overdue-total, and the sheet's
 * claimed-total, due-total and overdue-total (the totals leave out the single highest and lowest person's figure when
 * three or more people have one). A change takes them before it writes, then {@link #record} audits the ones it moved: a ROLLUP line
 * per person whose figures changed (in the order they were added; a new person counts as changed), then a TOTALS
 * line when the sheet's totals changed.
 */
@Service
public class Rollup {

    /**
     * A person's figures: claimed (two decimals), due-total (two decimals, or n/a) and overdue-total (the dues of
     * their counted overdue claims, two decimals).
     */
    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
    }

    /** The sheet's figures at one moment: per person id, in the order they were added, and the totals. */
    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {
    }

    private final People people;
    private final Claims claims;
    private final Rates rates;
    private final SheetClock clock;
    private final Settings settings;
    private final Audit audit;

    public Rollup(People people, Claims claims, Rates rates, SheetClock clock, Settings settings, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.clock = clock;
        this.settings = settings;
        this.audit = audit;
    }

    /** The sheet's figures now. */
    public Snapshot take(String sheet) {
        LocalDate today = clock.today(sheet);
        List<Rate> sheetRates = rates.list(sheet);
        Dated floor = settings.floor(sheet);
        BigDecimal cap = settings.cap(sheet);
        Late late = settings.late(sheet, today);
        List<Claim> all = claims.list(sheet);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        List<BigDecimal> dueFigures = new ArrayList<>();
        List<BigDecimal> overdueFigures = new ArrayList<>();
        for (Person person : people.list(sheet)) {
            List<Claim> mine = all.stream().filter((c) -> c.person() == person.id() && person.counts(c)).toList();
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
            for (Claim claim : mine) {
                claimed = claimed.add(new BigDecimal(claim.amount()));
                BigDecimal d = claim.due(sheetRates, person.gradeOn(claim.date()), floor, late);
                due = d == null ? due : due.add(d);
                if (d != null && late.overdue(claim, person.gradeOn(claim.date()))) {
                    overdue = overdue.add(d);
                }
            }
            // n/a when the grade has no rate on the sheet's today, unless a claim has a figure apart from it.
            boolean na = Rate.on(sheetRates, person.grade(), today) == null
                    && mine.stream().noneMatch((c) -> person.figureApartFrom(c, today, sheetRates, floor));
            due = Settings.capped(due, cap);
            claimedTotal = claimedTotal.add(claimed);
            overdueFigures.add(overdue);
            if (!na) {
                dueFigures.add(due);
            }
            figures.put(person.id(), new Figures(person.name(), claimed.toPlainString(), na ? "n/a" : due.toPlainString(),
                    overdue.toPlainString()));
        }
        return new Snapshot(figures, claimedTotal.toPlainString(), trimmedSum(dueFigures).toPlainString(),
                trimmedSum(overdueFigures).toPlainString());
    }

    /** Adds up the people's figures, leaving out the single highest and the single lowest when three or more have one. */
    static BigDecimal trimmedSum(List<BigDecimal> figures) {
        BigDecimal sum = figures.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        if (figures.size() < 3) {
            return sum;
        }
        return sum.subtract(Collections.max(figures)).subtract(Collections.min(figures));
    }

    /** Audits the figures the change moved since {@code before}, after the change's own lines. */
    public void record(String sheet, String user, Snapshot before) {
        Snapshot after = take(sheet);
        String prefix = " sheet=" + sheet + " by=" + user + " ";
        for (Map.Entry<Long, Figures> entry : after.people().entrySet()) {
            Figures now = entry.getValue();
            Figures was = before.people().get(entry.getKey());
            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())
                    || !was.overdueTotal().equals(now.overdueTotal())) {
                audit.record("ROLLUP" + prefix + "person=" + now.name() + " claimed=" + now.claimed() + " due-total="
                        + now.dueTotal() + " overdue-total=" + now.overdueTotal());
            }
        }
        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
                || !Objects.equals(before.dueTotal(), after.dueTotal())
                || !Objects.equals(before.overdueTotal(), after.overdueTotal())) {
            audit.record("TOTALS" + prefix + "claimed-total=" + after.claimedTotal() + " due-total=" + after.dueTotal()
                    + " overdue-total=" + after.overdueTotal());
        }
    }
}
package net.officefloor.hq.app.person;

import java.sql.Date;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.alias.Aliases;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The people kept per sheet, each with their grades by from-date. */
@Repository
public class People {

    private static final String COLUMNS = "SELECT id, name, version, retired_from, terms, contact FROM person";

    private record Row(long id, String name, long version, String retiredFrom, Integer terms, String contact) {
    }

    private final JdbcTemplate jdbc;
    private final SheetClock clock;
    private final Aliases aliases;

    public People(JdbcTemplate jdbc, SheetClock clock, Aliases aliases) {
        this.jdbc = jdbc;
        this.clock = clock;
        this.aliases = aliases;
    }

    private List<Person> query(String sheet, String where, Object... args) {
        List<Row> rows = jdbc.query(COLUMNS + " " + where, (rs, i) -> new Row(rs.getLong("id"), rs.getString("name"),
                rs.getLong("version"),
                rs.getDate("retired_from") == null ? null : rs.getDate("retired_from").toLocalDate().toString(),
                rs.getObject("terms", Integer.class), rs.getString("contact")), args);
        if (rows.isEmpty()) {
            return List.of();
        }
        Map<Long, List<GradeFrom>> grades = new HashMap<>();
        jdbc.query("SELECT g.person_id, g.grade, g.from_date FROM person_grade g JOIN person p ON p.id = g.person_id"
                + " WHERE p.sheet = ? ORDER BY g.person_id, g.from_key", (rs) -> {
                    grades.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                            .add(new GradeFrom(rs.getString("grade"),
                                    rs.getDate("from_date") == null ? null : rs.getDate("from_date").toLocalDate().toString()));
                }, sheet);
        Map<Long, List<Hold>> holds = new HashMap<>();
        jdbc.query("SELECT h.person_id, h.from_date, h.to_date FROM person_hold h JOIN person p ON p.id = h.person_id"
                + " WHERE p.sheet = ? ORDER BY h.person_id, h.id", (rs) -> {
                    holds.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                            .add(new Hold(rs.getDate("from_date").toLocalDate().toString(),
                                    rs.getDate("to_date") == null ? null : rs.getDate("to_date").toLocalDate().toString()));
                }, sheet);
        LocalDate today = clock.today(sheet);
        List<Person> people = new ArrayList<>();
        for (Row r : rows) {
            List<GradeFrom> mine = List.copyOf(grades.getOrDefault(r.id(), List.of()));
            people.add(new Person(r.id(), r.name(), Person.gradeOn(mine, today), r.version(), r.retiredFrom(),
                    List.copyOf(holds.getOrDefault(r.id(), List.of())), mine, r.terms(),
                    Person.retiredOn(r.retiredFrom(), today), r.contact()));
        }
        return people;
    }

    /** Everyone on the sheet, in the order they were added. */
    public List<Person> list(String sheet) {
        return query(sheet, "WHERE sheet = ? ORDER BY id", sheet);
    }

    public Person find(String sheet, long id) {
        List<Person> found = query(sheet, "WHERE sheet = ? AND id = ?", sheet, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The person on the sheet with this name or alias, ignoring case; null when there is none. */
    public Person findByName(String sheet, String name) {
        List<Person> found = query(sheet, "WHERE sheet = ? AND name_key = LOWER(?)", sheet, name);
        if (found.isEmpty()) {
            found = query(sheet, "WHERE sheet = ? AND id IN (SELECT person_id FROM person_alias WHERE sheet = ?"
                    + " AND alias_key = LOWER(?))", sheet, sheet, name);
        }
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether someone on the sheet other than {@code except} has this name, ignoring case. */
    public boolean nameTaken(String sheet, String name, Long except) {
        Integer taken = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet = ? AND name_key = LOWER(?) AND (? IS NULL OR id <> ?)",
                Integer.class, sheet, name, except, except);
