      postJson<Alias[]>(byUser(`${peoplePath(sheet)}/${person.id}/aliases`, user), { alias }),
    onSuccess: (updated) => {
      queryClient.setQueryData(aliasesKey(sheet), updated);
      setTyped('');
    },
