import { useMutationState } from '@tanstack/react-query';
import type { MutationKey } from '@tanstack/react-query';

// Whether the mutation sent at `submittedAt` is the latest of those sharing `mutationKey`. Actions that live in
// separate components but share one error element (a row's actions) show their refusal only while it is the
// row's latest, so the next action on that row removes it.
export function useIsLatest(mutationKey: MutationKey, submittedAt: number): boolean {
  const times = useMutationState({ filters: { mutationKey }, select: (m) => m.state.submittedAt });
  return submittedAt >= Math.max(0, ...times);
}
import { useRef } from 'react';
import type { UseMutationResult } from '@tanstack/react-query';

// Sends a mutation unless one sent this way has not answered yet, so a form submitted twice in quick
// succession (a double click) stores one record. `isPending` only shows on the next render, too late
// for the second click; this guard is a ref, set before the first send returns.
export function useSubmitOnce<V>(mutation: UseMutationResult<unknown, unknown, V, unknown>) {
  const busy = useRef(false);
  return (vars: V) => {
    if (busy.current) return;
    busy.current = true;
    mutation.reset();
    mutation
      .mutateAsync(vars)
      .catch(() => {
        /* a refusal shows through the mutation's own error state */
      })
      .finally(() => {
        busy.current = false;
      });
  };
}
